  border-color: var(--color-accent);
  background-color: var(--color-accent);
  outline: none;
}

.navbar__toggle {
  display: none;
  flex-direction: column;
  justify-content: center;
  align-items: center;
  gap: 5px;
  width: 36px;
  height: 36px;
  padding: var(--space-1);
  border-radius: var(--border-radius-sm);
  transition: background-color var(--transition-fast);
}

.navbar__toggle:hover {
  background-color: var(--color-border);
}

.navbar__toggle span {
  display: block;
  width: 22px;
  height: 2px;
  background-color: var(--color-text-primary);
  border-radius: 2px;
  transition: transform var(--transition-base),
              opacity var(--transition-base);
}

.navbar__toggle.is-active span:nth-child(1) {
  transform: translateY(7px) rotate(45deg);
}

.navbar__toggle.is-active span:nth-child(2) {
  opacity: 0;
}

.navbar__toggle.is-active span:nth-child(3) {
  transform: translateY(-7px) rotate(-45deg);
}

/* ============================================================
   PASO 6 — COMPONENTE: HERO
   ============================================================ */
.hero {
  position: relative;
  min-height: 100vh;
  display: flex;
  align-items: center;
  background: linear-gradient(
    135deg,
    var(--color-primary) 0%,
    var(--color-secondary) 50%,
    var(--color-surface) 100%
  );
  overflow: hidden;
  padding-top: var(--navbar-height);
}

.hero::before {
  content: '';
  position: absolute;
  inset: 0;
  background: var(--color-overlay);
  z-index: var(--z-overlay);
  pointer-events: none;
}

.hero > .container {
  position: relative;
  z-index: calc(var(--z-overlay) + 1);
  display: grid;
  grid-template-columns: 1fr 1fr;
  align-items: center;
  gap: var(--grid-gap);
  padding-block: var(--space-7);
}

.hero__content {
  display: flex;
  flex-direction: column;
  gap: var(--space-3);
}

.hero__title {
  font-size: var(--font-size-3xl);
  font-weight: var(--font-weight-bold);
  line-height: var(--line-height-tight);
  color: var(--color-white);
}

.hero__title span {
  color: var(--color-accent);
}

.hero__subtitle {
  font-size: var(--font-size-md);
  color: var(--color-text-secondary);
  line-height: var(--line-height-base);
  max-width: 48ch;
}

.hero__cta {
  display: flex;
  flex-wrap: wrap;
  gap: var(--space-2);
  margin-top: var(--space-2);
}

.hero__media {
  display: flex;
  justify-content: center;
  align-items: center;
}

.hero__image {
  width: 100%;
  max-width: 520px;
  border-radius: var(--border-radius-lg);
  box-shadow: var(--shadow-lg);
  object-fit: cover;
  aspect-ratio: 4 / 3;
}

/* ============================================================
   PASO 7 — SECCIÓN HEADERS COMPARTIDOS
   ============================================================ */
.section__header {
  text-align: center;
  margin-bottom: var(--space-6);
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: var(--space-2);
}

.section__title {
  font-size: var(--font-size-2xl);
  font-weight: var(--font-weight-bold);
  color: var(--color-white);
  position: relative;
  padding-bottom: var(--space-2);
}

.section__title::after {
  content: '';
  position: absolute;
  bottom: 0;
  left: 50%;
  transform: translateX(-50%);
  width: 60px;
  height: 3px;
  background-color: var(--color-accent);
  border-radius: var(--border-radius-pill);
}

.section__subtitle {
  font-size: var(--font-size-md);
  color: var(--color-text-secondary);
  max-width: 60ch;
  line-height: var(--line-height-base);
}

/* ============================================================
   PASO 8 — SECCIÓN: SERVICIOS
   ============================================================ */
.servicios {
  background-color: var(--color-secondary);
}

.servicios__grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: var(--grid-gap);
}

.servicio-card {
  background-color: var(--color-surface);
  border: 1px solid var(--color-border);
  border-radius: var(--border-radius-lg);
  overflow: hidden;
  box-shadow: var(--shadow-sm);
  transition: transform var(--transition-base),
              box-shadow var(--transition-base),
              border-color var(--transition-base);
  display: flex;
  flex-direction: column;
}

.servicio-card:hover {
  transform: translateY(-6px);
  box-shadow: var(--shadow-lg);
  border-color: var(--color-accent);
}

.servicio-card__media {
  width: 100%;
  overflow: hidden;
  aspect-ratio: 16 / 9;
}

.servicio-card__image {
  width: 100%;
  height: 100%;
  object-fit: cover;
  transition: transform var(--transition-slow);
}

.servicio-card:hover .servicio-card__image {
  transform: scale(1.05);
}

.servicio-card__body {
  padding: var(--space-3);
  display: flex;
  flex-direction: column;
  gap: var(--space-2);
  flex: 1;
}

.servicio-card__title {
  font-size: var(--font-size-lg);
  font-weight: var(--font-weight-semibold);
  color: var(--color-white);
}

.servicio-card__desc {
  font-size: var(--font-size-sm);
  color: var(--color-text-secondary);
  line-height: var(--line-height-base);
  flex: 1;
}

/* ============================================================
   PASO 9 — SECCIÓN: ABOUT
   ============================================================ */
.about {
  background-color: var(--color-primary);
}

.about > .container {
  display: grid;
  grid-template-columns: 1fr 1fr;
  align-items: center;
  gap: var(--space-6);
}

.about__media {
  display: flex;
  justify-content: center;
}

.about__image {
  width: 100%;
  max-width: 480px;
  border-radius: var(--border-radius-lg);
  box-shadow: var(--shadow-lg);
  object-fit: cover;
  aspect-ratio: 3 / 4;
}

.about__content {
  display: flex;
  flex-direction: column;
  gap: var(--space-3);
}

.about__content .section__header {
  text-align: left;
  align-items: flex-start;
  margin-bottom: 0;
}

.about__content .section__title::after {
  left: 0;
  transform: none;
}

.about__text {
  font-size: var(--font-size-base);
  color: var(--color-text-secondary);
  line-height: var(--line-height-base);
}

.about__stats {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: var(--space-3);
  margin-top: var(--space-2);
}

.stat {
  display: flex;
  flex-direction: column;
  gap: var(--space-1);
  padding: var(--space-3);
  background-color: var(--color-surface);
  border: 1px solid var(--color-border);
  border-radius: var(--border-radius-md);
  text-align: center;
  transition: border-color var(--transition-base);
}

.stat:hover {
  border-color: var(--color-accent);
}

.stat__number {
  font-family: var(--font-primary);
  font-size: var(--font-size-xl);
  font-weight: var(--font-weight-bold);
  color: var(--color-accent);
  line-height: var(--line-height-tight);
}

.stat__label {
  font-size: var(--font-size-xs);
  color: var(--color-text-secondary);
  text-transform: uppercase;
  letter-spacing: 0.06em;
  font-weight: var(--font-weight-medium);
}

/* ============================================================
   PASO 10 — SECCIÓN: CONTACTO
   ============================================================ */
.contacto {
  background-color: var(--color-secondary);
}

.contacto__wrapper {
  max-width: 680px;
  margin-inline: auto;
}

.contact-form {
  display: flex;
  flex-direction: column;
  gap: var(--space-3);
  background-color: var(--color-surface);
  border: 1px solid var(--color-border);
  border-radius: var(--border-radius-lg);
  padding: var(--space-5);
  box-shadow: var(--shadow-md);
}

.form-group {
  display: flex;
  flex-direction: column;
  gap: var(--space-1);
}

.form-group__label {
  font-family: var(--font-primary);
  font-size: var(--font-size-sm);
  font-weight: var(--font-weight-semibold);
  color: var(--color-text-primary);
  letter-spacing: 0.03em;
}

.form-group__input {
  width: 100%;
  padding: var(--space-2) var(--space-3);
  background-color: var(--color-secondary);
  border: 1px solid var(--color-border);
  border-radius: var(--border-radius-md);
  color: var(--color-text-primary);
  font-size: var(--font-size-base);
  transition: border-color var(--transition-fast),
              box-shadow var(--transition-fast);
  outline: none;
}

.form-group__input::placeholder {
  color: var(--color-text-secondary);
}

.form-group__input:focus {
  border-color: var(--color-accent);
  box-shadow: 0 0 0 3px rgba(233, 69, 96, 0.2);
}

.form-group__input--textarea {
  resize: vertical;
  min-height: 140px;
}

.form-group__error {
  font-size: var(--font-size-xs);
  color: var(--color-accent);
  font-weight: var(--font-weight-medium);
  min-height: 1em;
}

.contact-form__submit {
  align-self: flex-start;
  padding: var(--space-2) var(--space-5);
  background-color: var(--color-accent);
  color: var(--color-white);
  font-family: var(--font-primary);
  font-size: var(--font-size-sm);
  font-weight: var(--font-weight-semibold);
  letter-spacing: 0.05em;
  text-transform: uppercase;
  border-radius: var(--border-radius-pill);
  box-shadow: var(--shadow-sm);
  transition: background-color var(--transition-base),
              box-shadow var(--transition-base),
              transform var(--transition-fast);
}

.contact-form__submit:hover,
.contact-form__submit:focus-visible {
  background-color: var(--color-accent-hover);
  box-shadow: var(--shadow-md);
  transform: translateY(-2px);
  outline: none;
}

.contact-form__submit:active {
  transform: translateY(0);
  box-shadow: var(--shadow-sm);
}

.contact-form__submit:disabled {
  opacity: 0.6;
  cursor: not-allowed;
  transform: none;
}

.contact-form__feedback {
  min-height: 1.5rem;
}

.contact-form__feedback-msg {
  font-size: var(--font-size-sm);
  font-weight: var(--font-weight-medium);
  padding: var(--space-2) var(--space-3);
  border-radius: var(--border-radius-md);
  display: none;
}

.contact-form__feedback-msg--success {
  background-color: rgba(39, 174, 96, 0.15);
  color: #27ae60;
  border: 1px solid rgba(39, 174, 96, 0.3);
  display: block;
}

.contact-form__feedback-msg--error {
  background-color: rgba(233, 69, 96, 0.15);
  color: var(--color-accent);
  border: 1px solid rgba(233, 69, 96, 0.3);
  display: block;
}

/* ============================================================
   PASO 11 — FOOTER
   ============================================================ */
.footer {
  background-color: var(--color-primary);
  border-top: 1px solid var(--color-border);
  padding-block: var(--space-5);
}

.footer > .container {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: var(--space-3);
  text-align: center;
}

.footer__logo {
  font-family: var(--font-primary);
  font-size: var(--font-size-lg);
  font-weight: var(--font-weight-bold);
  color: var(--color-white);
}

.footer__logo span {
  color: var(--color-accent);
}

.footer__nav {
  display: flex;
  flex-wrap: wrap;
  justify-content: center;
  gap: var(--space-3);
}

.footer__nav a {
  font-size: var(--font-size-sm);
  color: var(--color-text-secondary);
  transition: color var(--transition-fast);
}

.footer__nav a:hover {
  color: var(--color-accent);
}

.footer__copy {
  font-size: var(--font-size-xs);
  color: var(--color-text-secondary);
}

/* ============================================================
   PASO 12 — ANIMACIONES DE SCROLL
   ============================================================ */
.animate-on-scroll {
  opacity: 0;
  transform: translateY(30px);
  transition: opacity var(--transition-slow),
              transform var(--transition-slow);
}

.animate-on-scroll.is-visible {
  opacity: 1;
  transform: translateY(0);
}

.animate-on-scroll.delay-1 {
  transition-delay: 100ms;
}

.animate-on-scroll.delay-2 {
  transition-delay: 200ms;
}

.animate-on-scroll.delay-3 {
  transition-delay: 300ms;
}

/* ============================================================
   PASO 13 — MEDIA QUERIES (agrupadas al final)
   ============================================================ */

/* --- Tablet: ≤ 1024px --- */
@media (max-width: 1024px) {
  :root {
    --font-size-3xl: 2.75rem;
    --font-size-2xl: 2.25rem;
  }

  .hero > .container {
    grid-template-columns: 1fr;
    text-align: center;
  }

  .hero__subtitle {
    max-width: 100%;
  }

  .hero__cta {
    justify-content: center;
  }

  .hero__media {
    order: -1;
  }

  .hero__image {
    max-width: 400px;
  }

  .servicios__grid {
    grid-template-columns: repeat(2, 1fr);
  }

  .about > .container {
    grid-template-columns: 1fr;
    text-align: center;
  }

  .about__content .section__header {
    align-items: center;
    text-align: center;
  }

  .about__content .section__title::after {
    left: 50%;
    transform: translateX(-50%);
  }

  .about__media {
    order: -1;
  }

  .about__image {
    max-width: 400px;
    aspect-ratio: 16 / 9;
  }

  .about__stats {
    justify-items: center;
  }
}

/* --- Mobile: ≤ 768px --- */
@media (max-width: 768px) {
  :root {
    --font-size-3xl: 2rem;
    --font-size-2xl: 1.75rem;
    --font-size-lg: 1.25rem;
    --space-7: 4rem;
    --space-6: 3rem;
  }

  .navbar__menu {
    position: fixed;
    top: var(--navbar-height);
    left: 0;
    width: 100%;
    flex-direction: column;
    align-items: flex-start;
    gap: 0;
    background-color: var(--navbar-bg-scrolled);
    border-top: 1px solid var(--color-border);
    padding: var(--space-3);
    transform: translateY(-110%);
    opacity: 0;
    pointer-events: none;
    transition: transform var(--transition-base),
                opacity var(--transition-base);
    z-index: calc(var(--z-navbar) - 1);
  }

  .navbar__menu.is-open {
    transform: translateY(0);
    opacity: 1;
    pointer-events: auto;
  }

  .navbar__menu a {
    width: 100%;
    padding-block: var(--space-2);
    border-bottom: 1px solid var(--color-border);
    font-size: var(--font-size-base);
  }

  .navbar__menu a::after {
    display: none;
  }

  .navbar__lang-toggle {
    margin-top: var(--space-2);
  }

  .navbar__toggle {
    display: flex;
  }

  .servicios__grid {
    grid-template-columns: 1fr;
  }

  .about__stats {
    grid-template-columns: 1fr;
  }

  .contact-form {
    padding: var(--space-3);
  }

  .contact-form__submit {
    align-self: stretch;
    text-align: center;
  }

  .hero__image {
    max-width: 100%;
  }
}

/* --- Mobile pequeño: ≤ 480px --- */
@media (max-width: 480px) {
  :root {
    --font-size-3xl: 1.75rem;
    --font-size-2xl: 1.5rem;
    --container-padding: var(--space-2);
  }

  .hero__cta {
    flex-direction: column;
    align-items: stretch;
  }

  .hero__cta .btn {
    text-align: center;
    justify-content: center;
  }

  .about__stats {
    grid-template-columns: repeat(2, 1fr);
  }

  .footer__nav {
    flex-direction: column;
    gap: var(--space-2);
  }
}
